import Foundation

/// Loads docs/test-vectors.json (generated by the Node reference implementation).
struct Vectors: Decodable {
    struct Framing: Decodable {
        let name: String
        let payload: String
        let maxFragment: Int
        let fragments: [String]
    }

    struct Auth: Decodable {
        let secretHex: String
        let nonceB64: String
        let clientNonceB64: String
        let clientProofB64: String
        let serverProofB64: String
    }

    struct Status: Decodable {
        struct Expected: Decodable {
            let flags: Int
            let phase: String
            let configRev: UInt32
            let nextEventAt: UInt32
            let nextEventType: String
            let attemptsRemaining: Int
        }

        let hex: String
        let expected: Expected
    }

    let framing: [Framing]
    let auth: Auth
    let status: [Status]

    static func load(file: StaticString = #filePath) throws -> Vectors {
        // .../ios/CameraTriggerKit/Tests/CameraTriggerKitTests/Vectors.swift -> repo root
        var url = URL(fileURLWithPath: "\(file)")
        for _ in 0 ..< 5 { url.deleteLastPathComponent() }
        let data = try Data(contentsOf: url.appendingPathComponent("docs/test-vectors.json"))
        return try JSONDecoder().decode(Vectors.self, from: data)
    }
}

extension Data {
    init?(hex: String) {
        guard hex.count % 2 == 0 else { return nil }
        var bytes = [UInt8]()
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            guard let byte = UInt8(hex[index ..< next], radix: 16) else { return nil }
            bytes.append(byte)
            index = next
        }
        self.init(bytes)
    }

    var hex: String { map { String(format: "%02x", $0) }.joined() }
}
